CREATE TABLE IF NOT EXISTS meetings (id TEXT PRIMARY KEY, secret TEXT NOT NULL, title TEXT NOT NULL, schedule TEXT NOT NULL, phase TEXT NOT NULL DEFAULT 'collect', agenda TEXT NOT NULL DEFAULT '[]', notes TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS topics (id TEXT PRIMARY KEY, meeting TEXT NOT NULL REFERENCES meetings(id), label TEXT NOT NULL, detail TEXT NOT NULL, kind TEXT NOT NULL, created BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS votes (meeting TEXT NOT NULL REFERENCES meetings(id), voter TEXT NOT NULL, pick1 TEXT NOT NULL DEFAULT '', pick2 TEXT NOT NULL DEFAULT '', PRIMARY KEY(meeting,voter));
ALTER TABLE meetings ADD COLUMN IF NOT EXISTS starts_at TIMESTAMPTZ;
ALTER TABLE meetings ADD COLUMN IF NOT EXISTS timezone TEXT NOT NULL DEFAULT 'UTC';
ALTER TABLE meetings ADD COLUMN IF NOT EXISTS duration INTEGER NOT NULL DEFAULT 60;
ALTER TABLE meetings ADD COLUMN IF NOT EXISTS location TEXT NOT NULL DEFAULT '';
ALTER TABLE meetings ADD COLUMN IF NOT EXISTS sent TEXT NOT NULL DEFAULT '{}';
ALTER TABLE topics ADD COLUMN IF NOT EXISTS announced BOOLEAN NOT NULL DEFAULT true;
CREATE TABLE IF NOT EXISTS subscribers (id TEXT PRIMARY KEY, meeting TEXT NOT NULL REFERENCES meetings(id), email TEXT NOT NULL, token TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'pending', invited BIGINT NOT NULL DEFAULT 0, UNIQUE(meeting,email));
CREATE TABLE IF NOT EXISTS ballots (topic TEXT NOT NULL REFERENCES topics(id), meeting TEXT NOT NULL REFERENCES meetings(id), voter TEXT NOT NULL, value SMALLINT NOT NULL, PRIMARY KEY(topic,voter));
INSERT INTO ballots (topic,meeting,voter,value) SELECT v.pick1,v.meeting,'c:'||v.voter,1 FROM votes v JOIN topics t ON t.id=v.pick1 ON CONFLICT DO NOTHING;
INSERT INTO ballots (topic,meeting,voter,value) SELECT v.pick2,v.meeting,'c:'||v.voter,1 FROM votes v JOIN topics t ON t.id=v.pick2 ON CONFLICT DO NOTHING;
DELETE FROM votes;
ALTER TABLE topics ADD COLUMN IF NOT EXISTS author TEXT NOT NULL DEFAULT '';
ALTER TABLE topics ADD COLUMN IF NOT EXISTS hidden BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE subscribers ADD COLUMN IF NOT EXISTS voter TEXT NOT NULL DEFAULT '';
CREATE TABLE IF NOT EXISTS outbox (id TEXT PRIMARY KEY, meeting TEXT NOT NULL, recipient TEXT NOT NULL, message TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'queued', attempts INTEGER NOT NULL DEFAULT 0, created BIGINT NOT NULL, updated BIGINT NOT NULL, error TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS outbox_status ON outbox (status, created);
CREATE TABLE IF NOT EXISTS rate_events (key TEXT NOT NULL, at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS rate_events_key ON rate_events (key, at)
